{"content": "import test from 'node:test';
import assert from 'node:assert/strict';
import { callTool, listTools } from './server.mjs';

test('slug', async () => {
  const r = await callTool('text_transform', { text: ' Hello, MCP! ', mode: 'slug' });
  assert.equal(r.content[0].text, 'hello-mcp');
});

test('uppercase', async () => {
  const r = await callTool('text_transform', { text: 'hello', mode: 'uppercase' });
  assert.equal(r.content[0].text, 'HELLO');
});

test('lowercase', async () => {
  const r = await callTool('text_transform', { text: 'HELLO', mode: 'lowercase' });
  assert.equal(r.content[0].text, 'hello');
});

test('trim defaults to true', async () => {
  const r = await callTool('text_transform', { text: '  hi  ', mode: 'uppercase' });
  assert.equal(r.content[0].text, 'HI');
});

test('trim false keeps spaces', async () => {
  const r = await callTool('text_transform', { text: '  hi  ', mode: 'uppercase', trim: false });
  assert.equal(r.content[0].text, '  HI  ');
});

test('slug collapses runs of non-alphanumeric', async () => {
  const r = await callTool('text_transform', { text: 'a!!!b   c___d', mode: 'slug' });
  assert.equal(r.content[0].text, 'a-b-c-d');
});

test('slug removes edge hyphens', async () => {
  const r = await callTool('text_transform', { text: '!!!hello!!!', mode: 'slug' });
  assert.equal(r.content[0].text, 'hello');
});

test('slug lowercases', async () => {
  const r = await callTool('text_transform', { text: 'Hello WORLD', mode: 'slug' });
  assert.equal(r.content[0].text, 'hello-world');
});

test('slug content type', async () => {
  const r = await callTool('text_transform', { text: 'x', mode: 'slug' });
  assert.equal(r.content[0].type, 'text');
});

test('rejects invalid mode', async () => {
  await assert.rejects(() => callTool('text_transform', { text: 'x', mode: 'nope' }), /mode/);
});

test('rejects missing text', async () => {
  await assert.rejects(() => callTool('text_transform', { mode: 'uppercase' }), /text/);
});

test('rejects missing mode', async () => {
  await assert.rejects(() => callTool('text_transform', { text: 'x' }), /mode/);
});

test('rejects non-string text', async () => {
  await assert.rejects(() => callTool('text_transform', { text: 5, mode: 'uppercase' }), /text/);
});

test('rejects non-boolean trim', async () => {
  await assert.rejects(() => callTool('text_transform', { text: 'x', mode: 'uppercase', trim: 'yes' }), /trim/);
});

test('rejects extra args', async () => {
  await assert.rejects(() => callTool('text_transform', { text: 'x', mode: 'uppercase', extra: 1 }), /extra/);
});

test('rejects unknown tool', async () => {
  await assert.rejects(() => callTool('nope', {}), /Unknown tool/);
});

test('listTools exposes text_transform schema', async () => {
  const tools = await listTools();
  assert.equal(tools.length, 1);
  assert.equal(tools[0].name, 'text_transform');
  const s = tools[0].inputSchema;
  assert.deepEqual(s.required, ['text', 'mode']);
  assert.equal(s.additionalProperties, false);
  assert.deepEqual(s.properties.mode.enum, ['uppercase', 'lowercase', 'slug']);
  assert.equal(s.properties.trim.default, true);
});
